            const rowBdr   = f.pass === true ? 'rgba(61,184,138,0.25)' : f.pass === false ? 'rgba(232,85,85,0.3)' : profile.bg3
            const passCol  = f.pass === true ? PASS : f.pass === false ? FAIL : TEXT3
